// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading
const { fontFamily: montserratFamily } = loadMontserrat();



export type TikTokOverlayProps = Record<string, any>;

// Helper for formatting large numbers
const formatCount = (num: number): string => {
  if (num >= 1000000) return (num / 1000000).toFixed(1).replace(/\.0$/, "") + "M";
  if (num >= 10000) return (num / 1000).toFixed(1).replace(/\.0$/, "") + "K";
  return num.toString();
};

const TikTokOverlay: React.FC<TikTokOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 10,
  username = "@malloy_studio",
  caption = "Creating stunning native UI overlays effortlessly. #design #motion #creative",
  profileImage = "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=300&q=80",
  likesStart = 12400,
  likesEnd = 13500,
  commentsStart = 840,
  commentsEnd = 865,
  engagementStartFrame = 40,
  iconColor = "#ffffff",
  textColor = "#ffffff",
  accentColor = "#ea4359", // TikTok red
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animations ---
  
  // Base UI Entrance (micro pops & fades)
  const uiEnterSpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8, stiffness: 120 },
  });

  const uiOpacity = interpolate(frame, [0, 8], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Engagement Counters (Rolling numbers)
  const engagementProgress = spring({
    frame: frame - engagementStartFrame,
    fps,
    config: { damping: 50, mass: 3, stiffness: 100 },
  });

  const currentLikes = Math.floor(
    likesStart + (likesEnd - likesStart) * engagementProgress
  );
  
  const currentComments = Math.floor(
    commentsStart + (commentsEnd - commentsStart) * engagementProgress
  );

  // Heart Pulse Interaction
  const isLiked = currentLikes > likesStart;
  const justLikedProgress = spring({
    frame: frame - engagementStartFrame,
    fps,
    config: { damping: 12, mass: 0.5, stiffness: 200 },
  });
  
  // Heart slightly pulses while numbers roll
  const heartScale = 1 + (justLikedProgress * 0.2) - (engagementProgress * 0.2);
  const heartColor = isLiked ? accentColor : iconColor;

  // Profile Follow Badge Out
  const followBadgeScale = spring({
    frame: frame - (engagementStartFrame - 10), // happens slightly before like
    fps,
    config: { damping: 12 },
  });
  const badgeCurrentScale = 1 - followBadgeScale;

  // --- Particle System for Heart ---
  const particles = Array.from({ length: 6 }).map((_, i) => {
    const pProgress = interpolate(
      frame - engagementStartFrame,
      [0, 20],
      [0, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );
    const angle = (i / 6) * Math.PI * 2;
    const distance = pProgress * 80;
    const x = Math.cos(angle) * distance;
    const y = Math.sin(angle) * distance - (pProgress * 40); // upward drift
    const opacity = interpolate(pProgress, [0, 0.7, 1], [0, 1, 0]);
    const scale = interpolate(pProgress, [0, 0.2, 1], [0.5, 1, 0]);
    
    return { x, y, opacity, scale };
  });

  // --- Shared Styles ---
  const textShadow = "0px 1px 4px rgba(0,0,0,0.6)";
  const iconFilter = "drop-shadow(0px 2px 6px rgba(0,0,0,0.4))";

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: montserratFamily, transition: "none" }}>
      
      {/* --- Right Vertical UI Stack --- */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.12,
          right: 20,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 32,
          opacity: uiOpacity,
          transform: `translateX(${(1 - uiEnterSpring) * 50}px)`,
          transition: "none",
        }}
      >
        {/* Profile */}
        <div style={{ position: "relative", width: 80, height: 80 }}>
          <Img
            src={profileImage}
            style={{
              width: "100%",
              height: "100%",
              borderRadius: "50%",
              border: `2px solid ${iconColor}`,
              objectFit: "cover",
            }}
          />
          {/* Follow Badge */}
          {badgeCurrentScale > 0 && (
            <div
              style={{
                position: "absolute",
                bottom: -10,
                left: "50%",
                transform: `translateX(-50%) scale(${badgeCurrentScale})`,
                backgroundColor: accentColor,
                width: 28,
                height: 28,
                borderRadius: "50%",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                border: "2px solid white",
              }}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="white">
                <path d="M19 11h-6V5h-2v6H5v2h6v6h2v-6h6z" />
              </svg>
            </div>
          )}
        </div>

        {/* Like */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6, position: "relative" }}>
          {isLiked && particles.map((p, i) => (
             <div key={i} style={{
               position: "absolute",
               top: 14,
               left: 14,
               width: 28,
               height: 28,
               opacity: p.opacity,
               transform: `translate(${p.x}px, ${p.y}px) scale(${p.scale})`,
               pointerEvents: "none",
             }}>
               <svg viewBox="0 0 24 24" fill={accentColor}>
                  <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
               </svg>
             </div>
          ))}
          <div style={{ transform: `scale(${heartScale})` }}>
            <svg width="56" height="56" viewBox="0 0 24 24" fill={heartColor} style={{ filter: iconFilter }}>
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </div>
          <span style={{ color: textColor, fontWeight: 600, fontSize: 20, textShadow }}>
            {formatCount(currentLikes)}
          </span>
        </div>

        {/* Comment */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
          <svg width="54" height="54" viewBox="0 0 24 24" fill={iconColor} style={{ filter: iconFilter }}>
            <path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm-2 12H6v-2h12v2zm0-3H6V9h12v2zm0-3H6V6h12v2z" />
          </svg>
          <span style={{ color: textColor, fontWeight: 600, fontSize: 20, textShadow }}>
            {formatCount(currentComments)}
          </span>
        </div>

        {/* Bookmark */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
          <svg width="52" height="52" viewBox="0 0 24 24" fill={iconColor} style={{ filter: iconFilter }}>
            <path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z" />
          </svg>
          <span style={{ color: textColor, fontWeight: 600, fontSize: 20, textShadow }}>
            82
          </span>
        </div>

        {/* Share */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
          <svg width="54" height="54" viewBox="0 0 24 24" fill={iconColor} style={{ filter: iconFilter }}>
            <path d="M14 6l6 6-6 6v-4c-5.5 0-9.5 1.5-12 5 1.5-5.5 5-8.5 12-9V6z" />
          </svg>
          <span style={{ color: textColor, fontWeight: 600, fontSize: 20, textShadow }}>
            34
          </span>
        </div>
      </div>

      {/* --- Lower Left Text Area --- */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.05,
          left: 24,
          width: width * 0.75,
          display: "flex",
          flexDirection: "column",
          gap: 12,
          opacity: uiOpacity,
          transform: `translateY(${(1 - uiEnterSpring) * 30}px)`,
          transition: "none",
        }}
      >
        <div style={{ color: textColor, fontWeight: 700, fontSize: 26, textShadow }}>
          {username}
        </div>
        
        <div
          style={{
            color: textColor,
            fontWeight: 400,
            fontSize: 22,
            lineHeight: 1.4,
            textShadow,
            whiteSpace: "pre-wrap",
          }}
        >
          {caption}
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default TikTokOverlay;